changeSet.sql:
ALTER TABLE user_tbl ADD COLUMN IF NOT EXISTS login varchar(255);

-- Для существующих пользователей логином становится chat_id (как было раньше),
-- новые пользователи пишут свой логин из формы регистрации
UPDATE user_tbl SET login = chat_id::text WHERE login IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_user_tbl_login ON user_tbl(login);
